/* The tax on orders from the shipped goods checkout, on the order rows themselves (Taxes, round X4). Since part 110 each order line has kept its tax in `orders.tax_cents` (and part 129 `tax_included`, part 153 `tax_label`), which is what Settings › Taxes' Tax collected, its CSV, the receipt and the business invoice read. The shipped goods checkout kept a line's tax only inside `orders.product_snapshot`, so those orders were missing from Tax collected and their invoice had no tax line. The code now writes the columns for every new order; this copies the same figure from each older line's own snapshot into the empty columns, and the country from its checkout's tax facts or delivery address. Only rows with a checkout, no tax recorded yet and a tax in their snapshot change, and only those empty columns; no amount, status or other column moves. Safe to run again: a second run finds nothing to copy. Until it runs, older shipped orders stay out of Tax collected and new ones are counted. */
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL OR to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'shipped order tax: no orders or checkouts yet.'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'tax_cents') OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'tax_country') THEN RAISE NOTICE 'shipped order tax: run part 110 first.'; RETURN; END IF; UPDATE public.orders o SET tax_cents = LEAST((o.product_snapshot->>'tax_cents')::bigint, GREATEST(o.amount_cents, 0)), tax_country = COALESCE(o.tax_country, (SELECT upper(COALESCE(NULLIF(c.shipping_rate->>'tax_country', ''), c.shipping_address->>'country')) FROM public.commerce_checkouts c WHERE c.id = o.checkout_id AND upper(COALESCE(NULLIF(c.shipping_rate->>'tax_country', ''), c.shipping_address->>'country', '')) ~ '^[A-Z]{2}$')) WHERE o.checkout_id IS NOT NULL AND COALESCE(o.tax_cents, 0) = 0 AND jsonb_typeof(o.product_snapshot) = 'object' AND (o.product_snapshot->>'tax_cents') ~ '^[0-9]{1,12}$' AND (o.product_snapshot->>'tax_cents')::bigint > 0; END $do$;
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RETURN; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'tax_included') THEN EXECUTE $q$UPDATE public.orders SET tax_included = true WHERE checkout_id IS NOT NULL AND COALESCE(tax_cents, 0) > 0 AND tax_included IS DISTINCT FROM true AND jsonb_typeof(product_snapshot) = 'object' AND product_snapshot->>'tax_included' = 'true'$q$; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'tax_label') THEN EXECUTE $q$UPDATE public.orders SET tax_label = left(btrim(product_snapshot->>'tax_label'), 80) WHERE checkout_id IS NOT NULL AND COALESCE(tax_cents, 0) > 0 AND tax_label IS NULL AND jsonb_typeof(product_snapshot) = 'object' AND COALESCE(btrim(product_snapshot->>'tax_label'), '') <> ''$q$; END IF; END $do$;
notify pgrst, 'reload schema';
